create table if not exists public.workstyle_profiles(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.customers(id) on delete cascade,assessment_id uuid not null references public.assessments(id) on delete cascade,model_version text not null,signals jsonb not null,reason_codes jsonb not null default '[]'::jsonb,created_at timestamptz not null default now()); alter table public.workstyle_profiles enable row level security; revoke all on public.workstyle_profiles from anon,authenticated; grant select on public.workstyle_profiles to authenticated; create policy workstyle_select_own on public.workstyle_profiles for select to authenticated using(exists(select 1 from public.customers c where c.id=customer_id and c.user_id=auth.uid()));
create table if not exists public.report_versions(id uuid primary key default gen_random_uuid(),blueprint_id uuid not null references public.blueprints(id) on delete cascade,content_version text not null,template_version text not null,renderer_version text,checksum text,storage_path text,status text not null default 'draft',created_at timestamptz not null default now()); alter table public.report_versions enable row level security;